# Roda dentro da pasta ouath-pages-theuzin
Write-Host 'Criando arquivos...'

# functions/_shared/cookies.js
$dir = Split-Path -Parent 'functions\_shared\cookies.js'
if($dir){ New-Item -ItemType Directory -Force -Path $dir | Out-Null }
$b64 = ''
$content = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($b64))
[System.IO.File]::WriteAllText((Join-Path $PWD 'functions\_shared\cookies.js'), $content, [System.Text.Encoding]::UTF8)
Write-Host 'OK functions\_shared\cookies.js'

